"""Discrete dynamics generated by a permutation matrix.

Origin: code/python/src/qm/campaigns/dynamics.py
Claim: the 3-cycle returns to the identity at the computed order 3 and not earlier.
AuthorityEffect: None.
"""
from fractions import Fraction


class DynamicsError(Exception):
    """The generator did not return to the identity inside the search bound."""


def _mul(left, right):
    size = len(left)
    return tuple(
        tuple(sum(left[i][k] * right[k][j] for k in range(size)) for j in range(size))
        for i in range(size)
    )


def _identity(size: int):
    return tuple(tuple(Fraction(1 if i == j else 0) for j in range(size)) for i in range(size))


def generator_order(matrix, bound: int = 24) -> int:
    """Smallest positive n with M^n = I, found by multiplying."""
    size = len(matrix)
    current = _identity(size)
    step = tuple(tuple(Fraction(entry) for entry in row) for row in matrix)
    for exponent in range(1, bound + 1):
        current = _mul(current, step)
        if current == _identity(size):
            return exponent
    raise DynamicsError(f"no return to the identity by exponent {bound}")


def three_cycle_order() -> int:
    cycle = (
        (0, 0, 1),
        (1, 0, 0),
        (0, 1, 0),
    )
    order = generator_order(cycle)
    if order != 3:
        raise DynamicsError(f"3-cycle order computed as {order}")
    return order
